def get_svg_icon(name: str, color: Optional[str] = "currentColor", size: int = 16, extra_class: str = "") -> str:
    """
    Retorna o código HTML do SVG inline estilo Font Awesome.
    """
    path_d = SVG_PATHS.get(name) or SVG_PATHS.get("sparkle")
    cls_str = f"brk-svg-icon {extra_class}".strip()
    return (
        f'<svg class="{cls_str}" width="{size}" height="{size}" viewBox="0 0 512 512" '
        f'fill="{color}" style="display:inline-block;vertical-align:-0.15em;flex-shrink:0;" '
        f'aria-hidden="true" xmlns="http://www.w3.org/2000/svg">'
        f'<path d="{path_d}"/>'
        f'</svg>'
    )
